do $$
begin
  if (select count(*) from devam_ganesha_tei_text_correction) <> 32 then
    raise exception 'Correction inventory is not exactly 32 rows';
  end if;
  if exists (
    select 1
    from devam_ganesha_tei_text_correction c
    left join public.source_objects s on s.sha256 = '21e5909392249ecca6677410c30d70323402d886975df807df2b865697fd9e6d'
    left join public.passages p
      on p.source_object_id = s.id and p.source_ordinal = c.source_ordinal
    where p.id is null
      or p.exact_text is distinct from c.expected_old_text
      or p.text_status <> 'tei_extracted_unreviewed'
      or p.span_sha256 <> c.span_sha256
      or p.rights_lane <> 'derivative_allowed'
      or p.publication_state <> c.expected_state
  ) then
    raise exception 'Hosted Ganesha TEI passage state drifted before correction';
  end if;
  if (select count(*) from public.source_objects where sha256 = '21e5909392249ecca6677410c30d70323402d886975df807df2b865697fd9e6d' and completeness_status = 'observed_32_units_structure_authority_unresolved') <> 1 then
    raise exception 'Source identity or unresolved completeness boundary drifted';
  end if;
  if (select count(*) from public.claim_evidence where note::jsonb ->> 'pack_id' = 'ganesha-shriganapatimantraksharavali-v1' and note::jsonb ->> 'pack_sha256' = '8449539fd96f4ce545a3d3c52ba875d8a19c27d3d1e2135314bf994846d37a3d') <> 10 then
    raise exception 'Prior knowledge-pack evidence identity drifted';
  end if;
end
$$;

update public.passages p
set exact_text = c.corrected_text,
    text_status = 'tei_text_note_anchors_excluded_unverified_against_print'
from public.source_objects s, devam_ganesha_tei_text_correction c
where s.sha256 = '21e5909392249ecca6677410c30d70323402d886975df807df2b865697fd9e6d'
  and p.source_object_id = s.id
  and p.source_ordinal = c.source_ordinal;

update public.claim_evidence
set note = (note::jsonb || jsonb_build_object('pack_sha256', '18c7aa230668b2d8062ebc31c9b366eb43f000d2210a39d84a2761843e7e0596'))::text
where note::jsonb ->> 'pack_id' = 'ganesha-shriganapatimantraksharavali-v1'
  and note::jsonb ->> 'pack_sha256' = '8449539fd96f4ce545a3d3c52ba875d8a19c27d3d1e2135314bf994846d37a3d';

do $$
begin
  if exists (
    select 1
    from devam_ganesha_tei_text_correction c
    join public.source_objects s on s.sha256 = '21e5909392249ecca6677410c30d70323402d886975df807df2b865697fd9e6d'
    join public.passages p on p.source_object_id = s.id and p.source_ordinal = c.source_ordinal
    where p.exact_text is distinct from c.corrected_text
      or p.text_status <> 'tei_text_note_anchors_excluded_unverified_against_print'
      or p.span_sha256 <> c.span_sha256
      or p.publication_state <> c.expected_state
      or p.exact_text ~ '[0-9]'
  ) then
    raise exception 'Corrected Ganesha TEI projection failed postcondition';
  end if;
  if (select count(*) from public.claim_evidence where note::jsonb ->> 'pack_id' = 'ganesha-shriganapatimantraksharavali-v1' and note::jsonb ->> 'pack_sha256' = '18c7aa230668b2d8062ebc31c9b366eb43f000d2210a39d84a2761843e7e0596') <> 10 then
    raise exception 'Corrected knowledge-pack evidence identity failed postcondition';
  end if;
end
$$;

commit;
